namespace blink::mojom::blink {


void SpeculationHostInterceptorForTesting::UpdateSpeculationCandidates(::blink::Vector<SpeculationCandidatePtr> candidates, bool enable_cross_origin_prerender_iframes) {
  GetForwardingInterface()->UpdateSpeculationCandidates(
    std::move(candidates)
    , 
    std::move(enable_cross_origin_prerender_iframes)
    );
}
void SpeculationHostInterceptorForTesting::OnLCPPredicted() {
  GetForwardingInterface()->OnLCPPredicted();
}
void SpeculationHostInterceptorForTesting::EnactCandidate(SpeculationCandidatePtr candidate, SpeculationHeuristic heuristic) {
  GetForwardingInterface()->EnactCandidate(
    std::move(candidate)
    , 
    std::move(heuristic)
    );
}
SpeculationHostAsyncWaiter::SpeculationHostAsyncWaiter(
    SpeculationHost* proxy) : proxy_(proxy) {}

SpeculationHostAsyncWaiter::~SpeculationHostAsyncWaiter() = default;







}  // blink::mojom::blink


